{"command": "python3 <<'PY'
import os, pty, subprocess, select

def run_test(stdout_pty, stderr_pty, force_val):
    env=dict(os.environ)
    if force_val is None:
        env.pop("RICHGO_FORCE_COLOR",None)
    else:
        env["RICHGO_FORCE_COLOR"]=force_val
    m_out=s_out=None
    m_err=s_err=None
    stdout_arg=subprocess.PIPE
    stderr_arg=subprocess.PIPE
    if stdout_pty:
        m_out,s_out=pty.openpty()
        stdout_arg=s_out
    if stderr_pty:
        m_err,s_err=pty.openpty()
        stderr_arg=s_err
    # run richgo test in /tmp/probe1
    p=subprocess.Popen(["/workspace/executable","test","-v","./..."], cwd="/tmp/probe1", stdout=stdout_arg, stderr=stderr_arg, env=env)
    if stdout_pty: os.close(s_out)
    if stderr_pty: os.close(s_err)
    out_bytes=b""; err_bytes=b""
    out_str=""; err_str=""
    if not stdout_pty:
        # need to read? p.communicate would handle, but we already have Popen without stdin
        # stdout is pipe, read
        pass
    # Use communicate for pipes? But we have mixed pty/pipes - handle
    # For pipes, we can read via p.stdout.read after wait? Simpler: use threads?
    # Let's just use p.communicate for pipe parts and select for pty
    # Actually if stdout is pipe and stderr is pty, p.stderr is not a pipe (it's fd), so communicate not good.
    # We'll manually read.
    import threading
    def read_pipe(pipe, container):
        try:
            data=pipe.read()
            container.append(data)
        except: container.append("")
    out_c=[]; err_c=[]
    t1=t2=None
    if not stdout_pty:
        import threading
        t1=threading.Thread(target=read_pipe, args=(p.stdout, out_c))
        t1.start()
    if not stderr_pty:
        t2=threading.Thread(target=read_pipe, args=(p.stderr, err_c))
        t2.start()
    # read pty masters
    out_pty_data=b""; err_pty_data=b""
    import select, time
    # need to poll until process exits
    # Use select loop
    masters=[]
    if stdout_pty: masters.append((m_out, "out"))
    if stderr_pty: masters.append((m_err, "err"))
    # We'll read with timeout
    start=time.time()
    buffers={"out":b"", "err":b""}
    fds={m_out:"out"} if stdout_pty else {}
    if stderr_pty: fds[m_err]="err"
    # non-blocking loop
    while time.time()-start<5:
        if not fds: break
        r,_,_=select.select(list(fds.keys()), [], [], 0.3)
        for fd in r:
            try:
                data=os.read(fd, 4096)
                if not data:
                    # EOF? remove?
                    del fds[fd]
                else:
                    buffers[fds[fd]]+=data
            except OSError:
                del fds[fd]
        if p.poll() is not None and not fds:
            break
        if p.poll() is not None:
            # drain remaining?
            continue
    p.wait(timeout=5)
    if t1: t1.join(timeout=2)
    if t2: t2.join(timeout=2)
    if stdout_pty:
        try: os.close(m_out)
        except: pass
        out_str=buffers["out"].decode(errors="replace")
    else:
        out_str=out_c[0] if out_c else ""
    if stderr_pty:
        try: os.close(m_err)
        except: pass
        err_str=buffers["err"].decode(errors="replace")
    else:
        err_str=err_c[0] if err_c else ""
    return out_str, err_str, p.returncode

for so in [False, True]:
    for se in [False, True]:
        for fv in [None, "1"]:
            o,e,c=run_test(so,se,fv)
            print(f"stdout_pty={so} stderr_pty={se} force={repr(fv)} code={c}")
            print(f"  OUT={repr(o[:300])}")
            print(f"  ERR={repr(e[:300])}")
PY"}

