    print(f"pipes force={repr(fv)} => OUT={repr(o)} ERR={repr(e)}")
for fv in ["", None]:
    o,e=run_matrix(False, True, fv)
    print(f"stderr pty force={repr(fv)} => OUT={repr(o)} ERR={repr(e)}")
