// ---------- Color ----------

type Color struct {
	raw string
	isRGB bool
	r, g, b int
	namedFg string // e.g. "\x1b[31m" for fg, but we store name and compute later?
	namedBg string
	isNamed bool
	name string
}

var namedFgCodes = map[string]string{
	"black": "\x1b[30m",
	"red": "\x1b[31m",
	"green": "\x1b[32m",
	"yellow": "\x1b[33m",
	"blue": "\x1b[34m",
	"magenta": "\x1b[35m",
