	"lightYellow": "\x1b[93m",
	"lightBlue": "\x1b[94m",
	"lightMagenta": "\x1b[95m",
	"lightCyan": "\x1b[96m",
	"lightWhite": "\x1b[97m",
}

var namedBgCodes = map[string]string{
	"black": "\x1b[40m",
	"red": "\x1b[41m",
	"green": "\x1b[42m",
	"yellow": "\x1b[43m",
	"blue": "\x1b[44m",
	"magenta": "\x1b[45m",
	"cyan": "\x1b[46m",
	"white": "\x1b[47m",
	"lightBlack": "\x1b[100m",
	"lightRed": "\x1b[101m",
	"lightGreen": "\x1b[102m",
	"lightYellow": "\x1b[103m",
	"lightBlue": "\x1b[104m",
	"lightMagenta": "\x1b[105m",
	"lightCyan": "\x1b[106m",
	"lightWhite": "\x1b[107m",
}

func parseColor(s string) (Color, error) {
	if code, ok := namedFgCodes[s]; ok {
		_ = code
		return Color{raw: s, isNamed: true, name: s}, nil
	}
	// hex #rrggbb
	if matched, _ := regexp.MatchString(`^#[0-9a-fA-F]{6}$`, s); matched {
		r, _ := strconv.ParseInt(s[1:3], 16, 0)
		g, _ := strconv.ParseInt(s[3:5], 16, 0)
		b, _ := strconv.ParseInt(s[5:7], 16, 0)
		return Color{raw: s, isRGB: true, r: int(r), g: int(g), b: int(b)}, nil
	}
	// rgb(...)
	// pattern: rgb\(num,num,num\) where num is decimal 0-255 (1-3 digits) or 0x.. hex 2 digits, case-insensitive rgb, spaces only after comma (zero or more)
	// No spaces after '(' or before ')', no spaces before comma
	// Use regex to validate and extract
	// rgb case-insensitive
	re := regexp.MustCompile(`^[Rr][Gg][Bb]\(([^,]+), *( [^,]+)?`)
	_ = re
	// Manual parse for strictness
	if len(s) < 5 {
		return Color{}, fmt.Errorf("invalid format")
	}
	// check prefix case-insensitive "rgb("
	if !strings.HasPrefix(strings.ToLower(s), "rgb(") || !strings.HasSuffix(s, ")") {
		return Color{}, fmt.Errorf("invalid format")
	}
	inner := s[4 : len(s)-1]
	// split by comma, must be exactly 3 parts
	parts := strings.Split(inner, ",")
	if len(parts) != 3 {
		return Color{}, fmt.Errorf("invalid format")
	}
	// check spaces: after '(' no space (first part must not start with space), before ')' no space (last part must not end with space), before comma no space
	// Actually parts[0] must not have leading/trailing spaces? Since inner starts right after '(', parts[0] is first number, must not start with space and must not end with space (space before comma not allowed)
	// parts[1], parts[2] may have leading spaces (after comma), but must not have trailing spaces except? For parts[1], trailing space before comma not allowed? Actually parts[1] is between commas, must not end with space? Wait "rgb(255,  0, 0)" has parts ["255", "  0", " 0"]? No, split by "," gives ["255", "  0", " 0"]. First part "255" has no spaces, good. Second "  0" has leading spaces (allowed), no trailing? It ends with "0", good. Third " 0" has leading space, ends with "0", good (no trailing before ')', since ')' follows). So rule: parts[0] must match ^(dec|hex)$ with no spaces; parts[1], parts[2] must match ^ * (dec|hex)$ with leading spaces allowed, no trailing.
	// Also need to ensure no spaces before comma: that means parts[0] must not end with space, parts[1] must not end with space. Since split removes comma, trailing spaces in parts[0]/parts[1] would indicate space before comma. So check.
	for i, p := range parts {
		if i == 0 {
			if p == "" || strings.HasPrefix(p, " ") || strings.HasSuffix(p, " ") {
				return Color{}, fmt.Errorf("invalid format")
			}
		} else {
			// allow leading spaces, but not trailing? Actually trailing spaces would be before next comma or before ')'. For parts[1], trailing space would be space before comma -> not allowed. For parts[2], trailing space would be space before ')' -> not allowed.
			if p == "" {
				return Color{}, fmt.Errorf("invalid format")
			}
			// check trailing space
			if strings.HasSuffix(p, " ") {
				return Color{}, fmt.Errorf("invalid format")
			}
			// strip leading spaces for validation
			stripped := strings.TrimLeft(p, " ")
			// stripped must not contain spaces inside? It should be just number, no spaces. Since we allow only spaces after comma, stripped should have no spaces.
			if strings.Contains(stripped, " ") {
				return Color{}, fmt.Errorf("invalid format")
			}
			parts[i] = stripped
		}
		// validate number
		numStr := parts[i]
		// check if hex (0x..)
		if len(numStr) >= 3 && (strings.HasPrefix(numStr, "0x") || strings.HasPrefix(numStr, "0X")) {
			hexPart := numStr[2:]
			if len(hexPart) != 2 {
				return Color{}, fmt.Errorf("invalid format")
			}
			if matched, _ := regexp.MatchString(`^[0-9a-fA-F]{2}$`, hexPart); !matched {
				return Color{}, fmt.Errorf("invalid format")
			}
		} else {
			// decimal: 1-3 digits, value 0-255
			if matched, _ := regexp.MatchString(`^[0-9]{1,3}$`, numStr); !matched {
				return Color{}, fmt.Errorf("invalid format")
			}
			v, _ := strconv.Atoi(numStr)
			if v < 0 || v > 255 {
				return Color{}, fmt.Errorf("invalid format")
			}
		}
	}
	// convert to rgb values
	var vals [3]int
	for i, p := range parts {
		if len(p) >= 3 && (strings.HasPrefix(p, "0x") || strings.HasPrefix(p, "0X")) {
			v, _ := strconv.ParseInt(p[2:], 16, 0)
			vals[i] = int(v)
		} else {
			v, _ := strconv.Atoi(p)
			vals[i] = v
		}
	}
	return Color{raw: s, isRGB: true, r: vals[0], g: vals[1], b: vals[2]}, nil
}

func (c Color) FgCode() string {
	if c.isRGB {
		return fmt.Sprintf("\x1b[38;2;%d;%d;%dm", c.r, c.g, c.b)
	}
	if c.isNamed {
		if code, ok := namedFgCodes[c.name]; ok {
			return code
		}
	}
	return ""
}

func (c Color) BgCode() string {
	if c.isRGB {
		return fmt.Sprintf("\x1b[48;2;%d;%d;%dm", c.r, c.g, c.b)
	}
	if c.isNamed {
		if code, ok := namedBgCodes[c.name]; ok {
			return code
		}
	}
	return ""
}

func (c *Color) UnmarshalYAML(value *yaml.Node) error {
	var s string
	if err := value.Decode(&s); err != nil {
		return err
	}
	parsed, err := parseColor(s)
	if err != nil {
		return fmt.Errorf("invalid format")
	}
	*c = parsed
	return nil
}

// ---------- Style ----------

type Style struct {
	Hide       bool
	Bold       bool
	Faint      bool
	Italic     bool
	Underline  bool
	BlinkSlow  bool
	BlinkRapid bool
	Inverse    bool
	Conceal    bool
	CrossOut   bool
	Frame      bool
	Encircle   bool
	Overline   bool
	Foreground *Color
	Background *Color
}

func (s Style) Prefix() string {
	var b strings.Builder
	if s.Background != nil {
		b.WriteString(s.Background.BgCode())
	}
	if s.Foreground != nil {
		b.WriteString(s.Foreground.FgCode())
	}
	if s.Bold {
		b.WriteString("\x1b[1m")
	}
	if s.Faint {
		b.WriteString("\x1b[2m")
	}
	if s.Italic {
		b.WriteString("\x1b[3m")
	}
	if s.Underline {
		b.WriteString("\x1b[4m")
	}
	if s.BlinkSlow {
		b.WriteString("\x1b[5m")
	}
	if s.BlinkRapid {
		b.WriteString("\x1b[6m")
	}
	if s.Inverse {
		b.WriteString("\x1b[7m")
	}
	if s.Conceal {
		b.WriteString("\x1b[8m")
	}
	if s.CrossOut {
		b.WriteString("\x1b[9m")
	}
	if s.Frame {
		b.WriteString("\x1b[51m")
	}
	if s.Encircle {
		b.WriteString("\x1b[52m")
	}
	if s.Overline {
		b.WriteString("\x1b[53m")
	}
	return b.String()
}

func (s Style) Suffix() string {
	if s.Prefix() == "" {
		return ""
	}
	return "\x1b[0m"
}

