}

func defaultConfig() Config {
	yellow := mustColor("yellow")
	lightBlack := mustColor("lightBlack")
	green := mustColor("green")
	red := mustColor("red")
	cyan := mustColor("cyan")
	magenta := mustColor("magenta")
	return Config{
