	}
}

func mustColor(s string) Color {
	c, err := parseColor(s)
	if err != nil {
		panic(err)
	}
	return c
}

// File structs for merging with pointers
type StyleFile struct {
	Hide       *bool  `yaml:"hide"`
	Bold       *bool  `yaml:"bold"`
	Faint      *bool  `yaml:"faint"`
	Italic     *bool  `yaml:"italic"`
	Underline  *bool  `yaml:"underline"`
	BlinkSlow  *bool  `yaml:"blinkSlow"`
	BlinkRapid *bool  `yaml:"blinkRapid"`
	Inverse    *bool  `yaml:"inverse"`
	Conceal    *bool  `yaml:"conceal"`
	CrossOut   *bool  `yaml:"crossOut"`
	Frame      *bool  `yaml:"frame"`
	Encircle   *bool  `yaml:"encircle"`
	Overline   *bool  `yaml:"overline"`
	Foreground *Color `yaml:"foreground"`
	Background *Color `yaml:"background"`
}

type ConfigFile struct {
	LabelType        *string    `yaml:"labelType"`
	BuildStyle       *StyleFile `yaml:"buildStyle"`
	StartStyle       *StyleFile `yaml:"startStyle"`
	PassStyle        *StyleFile `yaml:"passStyle"`
	FailStyle        *StyleFile `yaml:"failStyle"`
	SkipStyle        *StyleFile `yaml:"skipStyle"`
	FileStyle        *StyleFile `yaml:"fileStyle"`
	LineStyle        *StyleFile `yaml:"lineStyle"`
	PassPackageStyle *StyleFile `yaml:"passPackageStyle"`
	FailPackageStyle *StyleFile `yaml:"failPackageStyle"`
	CoverThreshold   *int       `yaml:"coverThreshold"`
	CoveredStyle     *StyleFile `yaml:"coveredStyle"`
	UncoveredStyle   *StyleFile `yaml:"uncoveredStyle"`
	Removals         *[]string  `yaml:"removals"`
	LeaveTestPrefix  *bool      `yaml:"leaveTestPrefix"`
}

func mergeStyle(dst *Style, src *StyleFile) {
	if src == nil {
		return
	}
	if src.Hide != nil {
		dst.Hide = *src.Hide
	}
	if src.Bold != nil {
		dst.Bold = *src.Bold
	}
	if src.Faint != nil {
		dst.Faint = *src.Faint
	}
	if src.Italic != nil {
		dst.Italic = *src.Italic
	}
	if src.Underline != nil {
		dst.Underline = *src.Underline
	}
	if src.BlinkSlow != nil {
		dst.BlinkSlow = *src.BlinkSlow
	}
	if src.BlinkRapid != nil {
		dst.BlinkRapid = *src.BlinkRapid
	}
	if src.Inverse != nil {
		dst.Inverse = *src.Inverse
	}
	if src.Conceal != nil {
		dst.Conceal = *src.Conceal
	}
	if src.CrossOut != nil {
		dst.CrossOut = *src.CrossOut
	}
	if src.Frame != nil {
		dst.Frame = *src.Frame
	}
	if src.Encircle != nil {
		dst.Encircle = *src.Encircle
	}
	if src.Overline != nil {
		dst.Overline = *src.Overline
	}
	if src.Foreground != nil {
		c := *src.Foreground
		dst.Foreground = &c
	}
	if src.Background != nil {
