		dst.Background = &c
	}
}

func loadConfig() Config {
	cfg := defaultConfig()
	var paths []string
	cwd, err := os.Getwd()
	if err == nil {
		paths = append(paths, filepath.Join(cwd, ".richstyle"), filepath.Join(cwd, ".richstyle.yaml"), filepath.Join(cwd, ".richstyle.yml"))
	}
	if os.Getenv("RICHGO_LOCAL") != "1" {
		if gopath := os.Getenv("GOPATH"); gopath != "" {
			paths = append(paths, filepath.Join(gopath, ".richstyle"), filepath.Join(gopath, ".richstyle.yaml"), filepath.Join(gopath, ".richstyle.yml"))
		}
		goroot := os.Getenv("GOROOT")
		if goroot == "" {
			goroot = runtime.GOROOT()
		}
		if goroot != "" {
			paths = append(paths, filepath.Join(goroot, ".richstyle"), filepath.Join(goroot, ".richstyle.yaml"), filepath.Join(goroot, ".richstyle.yml"))
		}
		if home := os.Getenv("HOME"); home != "" {
			paths = append(paths, filepath.Join(home, ".richstyle"), filepath.Join(home, ".richstyle.yaml"), filepath.Join(home, ".richstyle.yml"))
		}
	}
	for _, p := range paths {
		data, err := os.ReadFile(p)
		if err != nil {
			continue
		}
		var cf ConfigFile
		if err := yaml.Unmarshal(data, &cf); err != nil {
			log.Printf("error unmarshaling yaml from %s :  %v", p, err)
			continue
		}
		// merge
		if cf.LabelType != nil {
			cfg.LabelType = *cf.LabelType
		}
		mergeStyle(&cfg.BuildStyle, cf.BuildStyle)
		mergeStyle(&cfg.StartStyle, cf.StartStyle)
		mergeStyle(&cfg.PassStyle, cf.PassStyle)
		mergeStyle(&cfg.FailStyle, cf.FailStyle)
		mergeStyle(&cfg.SkipStyle, cf.SkipStyle)
		mergeStyle(&cfg.FileStyle, cf.FileStyle)
		mergeStyle(&cfg.LineStyle, cf.LineStyle)
		mergeStyle(&cfg.PassPackageStyle, cf.PassPackageStyle)
		mergeStyle(&cfg.FailPackageStyle, cf.FailPackageStyle)
		mergeStyle(&cfg.CoveredStyle, cf.CoveredStyle)
		mergeStyle(&cfg.UncoveredStyle, cf.UncoveredStyle)
		if cf.CoverThreshold != nil {
			cfg.CoverThreshold = *cf.CoverThreshold
		}
		if cf.Removals != nil {
			cfg.Removals = append(cfg.Removals, *cf.Removals...)
		}
		if cf.LeaveTestPrefix != nil {
			cfg.LeaveTestPrefix = *cf.LeaveTestPrefix
		}
	}
	// compile removals (panic on invalid to match original)
	for _, pat := range cfg.Removals {
		re := regexp.MustCompile(pat)
		cfg.removalRes = append(cfg.removalRes, re)
	}
	return cfg
}

// ---------- Helpers ----------

func isColorEnabled() bool {
	if os.Getenv("RICHGO_FORCE_COLOR") != "" {
		return true
	}
	return isatty.IsTerminal(os.Stderr.Fd())
}

func applyRemovalsToString(s string, res []*regexp.Regexp) string {
	for _, re := range res {
		s = re.ReplaceAllString(s, "")
	}
	return s
}

// label formatting
func formatLabel(labelType, longLabel, shortLabel string) string {
	switch labelType {
	case "short":
		// pad short to 2 + space
		padded := shortLabel
		if len(padded) < 2 {
			padded = padded + strings.Repeat(" ", 2-len(padded))
		}
		return padded + " "
	case "none":
		return ""
	default: // long and invalid? Actually invalid => none, long => long, empty => long
		// Need to handle: if labelType is "long" or "" => long, if "short" => short, else => none
		// This function is called with already resolved? We'll resolve outside.
		// For long: pad to 5 + "| "
		padded := longLabel
		if len(padded) < 5 {
			padded = padded + strings.Repeat(" ", 5-len(padded))
		}
		return padded + "| "
	}
}

func resolveLabel(labelType, longLabel, shortLabel string) string {
	if labelType == "short" {
		padded := shortLabel
		if len(padded) < 2 {
			padded = padded + strings.Repeat(" ", 2-len(padded))
		}
		return padded + " "
	}
	if labelType == "none" {
		return ""
	}
	if labelType == "long" || labelType == "" {
		padded := longLabel
		if len(padded) < 5 {
			padded = padded + strings.Repeat(" ", 5-len(padded))
		}
		return padded + "| "
	}
	// invalid => none
	return ""
}

// For generic label
func genericLabel(labelType string) string {
	if labelType == "short" {
		return "   "
	}
	if labelType == "none" {
		return ""
	}
	if labelType == "long" || labelType == "" {
		return "     | "
	}
	return ""
}

