			// check trailing space
			if strings.HasSuffix(p, " ") {
				return Color{}, fmt.Errorf("invalid format")
			}
			// strip leading spaces for validation
			stripped := strings.TrimLeft(p, " ")
			// stripped must not contain spaces inside? It should be just number, no spaces. Since we allow only spaces after comma, stripped should have no spaces.
			if strings.Contains(stripped, " ") {
				return Color{}, fmt.Errorf("invalid format")
			}
			parts[i] = stripped
		}
		// validate number
		numStr := parts[i]
		// check if hex (0x..)
		if len(numStr) >= 3 && (strings.HasPrefix(numStr, "0x") || strings.HasPrefix(numStr, "0X")) {
			hexPart := numStr[2:]
			if len(hexPart) != 2 {
				return Color{}, fmt.Errorf("invalid format")
			}
			if matched, _ := regexp.MatchString(`^[0-9a-fA-F]{2}$`, hexPart); !matched {
				return Color{}, fmt.Errorf("invalid format")
			}
		} else {
			// decimal: 1-3 digits, value 0-255
			if matched, _ := regexp.MatchString(`^[0-9]{1,3}$`, numStr); !matched {
				return Color{}, fmt.Errorf("invalid format")
			}
			v, _ := strconv.Atoi(numStr)
			if v < 0 || v > 255 {
				return Color{}, fmt.Errorf("invalid format")
			}
		}
	}
	// convert to rgb values
	var vals [3]int
	for i, p := range parts {
		if len(p) >= 3 && (strings.HasPrefix(p, "0x") || strings.HasPrefix(p, "0X")) {
			v, _ := strconv.ParseInt(p[2:], 16, 0)
			vals[i] = int(v)
		} else {
			v, _ := strconv.Atoi(p)
			vals[i] = v
		}
	}
	return Color{raw: s, isRGB: true, r: vals[0], g: vals[1], b: vals[2]}, nil
}

func (c Color) FgCode() string {
	if c.isRGB {
		return fmt.Sprintf("\x1b[38;2;%d;%d;%dm", c.r, c.g, c.b)
	}
	if c.isNamed {
		if code, ok := namedFgCodes[c.name]; ok {
			return code
		}
	}
	return ""
}

func (c Color) BgCode() string {
	if c.isRGB {
		return fmt.Sprintf("\x1b[48;2;%d;%d;%dm", c.r, c.g, c.b)
	}
	if c.isNamed {
		if code, ok := namedBgCodes[c.name]; ok {
			return code
		}
	}
	return ""
}

func (c *Color) UnmarshalYAML(value *yaml.Node) error {
	var s string
	if err := value.Decode(&s); err != nil {
		return err
	}
	parsed, err := parseColor(s)
	if err != nil {
		return fmt.Errorf("invalid format")
	}
	*c = parsed
	return nil
}

// ---------- Style ----------

type Style struct {
	Hide       bool
	Bold       bool
	Faint      bool
	Italic     bool
	Underline  bool
	BlinkSlow  bool
	BlinkRapid bool
	Inverse    bool
	Conceal    bool
	CrossOut   bool
	Frame      bool
	Encircle   bool
	Overline   bool
	Foreground *Color
	Background *Color
}

func (s Style) Prefix() string {
	var b strings.Builder
	if s.Background != nil {
		b.WriteString(s.Background.BgCode())
	}
	if s.Foreground != nil {
		b.WriteString(s.Foreground.FgCode())
	}
	if s.Bold {
		b.WriteString("\x1b[1m")
	}
	if s.Faint {
		b.WriteString("\x1b[2m")
	}
	if s.Italic {
		b.WriteString("\x1b[3m")
	}
	if s.Underline {
		b.WriteString("\x1b[4m")
	}
	if s.BlinkSlow {
		b.WriteString("\x1b[5m")
	}
	if s.BlinkRapid {
		b.WriteString("\x1b[6m")
	}
	if s.Inverse {
		b.WriteString("\x1b[7m")
	}
	if s.Conceal {
		b.WriteString("\x1b[8m")
	}
	if s.CrossOut {
		b.WriteString("\x1b[9m")
	}
	if s.Frame {
		b.WriteString("\x1b[51m")
	}
	if s.Encircle {
		b.WriteString("\x1b[52m")
	}
	if s.Overline {
		b.WriteString("\x1b[53m")
	}
	return b.String()
}

func (s Style) Suffix() string {
	if s.Prefix() == "" {
		return ""
	}
	return "\x1b[0m"
}

