var namedBgCodes = map[string]string{
	"black": "\x1b[40m",
	"red": "\x1b[41m",
	"green": "\x1b[42m",
	"yellow": "\x1b[43m",
	"blue": "\x1b[44m",
	"magenta": "\x1b[45m",
