func mergeStyle(dst *Style, src *StyleFile) {
	if src == nil {
		return
	}
	if src.Hide != nil {
		dst.Hide = *src.Hide
	}
	if src.Bold != nil {
		dst.Bold = *src.Bold
	}
	if src.Faint != nil {
		dst.Faint = *src.Faint
	}
