func (f *filter) styleFor(kind string) *Style {
	switch kind {
	case "build":
		return &f.cfg.BuildStyle
	case "start":
		return &f.cfg.StartStyle
	case "pass":
		return &f.cfg.PassStyle
	case "fail":
		return &f.cfg.FailStyle
	case "skip":
		return &f.cfg.SkipStyle
	case "cover-covered":
		return &f.cfg.CoveredStyle
	case "cover-uncovered":
		return &f.cfg.UncoveredStyle
	case "passpkg":
		return &f.cfg.PassPackageStyle
	case "failpkg":
		return &f.cfg.FailPackageStyle
	}
	return nil
}

