// START: ^=== RUN   Test(.*)$ with exactly 3 spaces
func matchStart(line string) *startMatch {
	prefix := "=== RUN   "
	if !strings.HasPrefix(line, prefix) {
		return nil
	}
	rest := line[len(prefix):]
	if !strings.HasPrefix(rest, "Test") {
		return nil
	}
	return &startMatch{rest: rest}
}

