import subprocess, os, pty, select
def run_pty(exe, inp, stdout_pty, stderr_pty, force_val):
    env=dict(os.environ)
    if force_val is None:
        env.pop("RICHGO_FORCE_COLOR",None)
    else:
        env["RICHGO_FORCE_COLOR"]=force_val
    m_out=s_out=None; m_err=s_err=None
    stdout_arg=subprocess.PIPE; stderr_arg=subprocess.PIPE
    if stdout_pty:
        m_out,s_out=pty.openpty(); stdout_arg=s_out
    if stderr_pty:
        m_err,s_err=pty.openpty(); stderr_arg=s_err
    p=subprocess.Popen([exe,"testfilter"], stdin=subprocess.PIPE, stdout=stdout_arg, stderr=stderr_arg, text=True, env=env)
    if stdout_pty: os.close(s_out)
    if stderr_pty: os.close(s_err)
    p.stdin.write(inp)
    p.stdin.close()
    out_str=""; err_str=""
    out_bytes=b""; err_bytes=b""
    if not stdout_pty:
        out_str=p.stdout.read()
    else:
        while True:
            r,_,_=select.select([m_out], [], [], 0.5)
            if not r: break
            try:
                data=os.read(m_out, 4096)
                if not data: break
                out_bytes+=data
            except: break
        out_str=out_bytes.decode(errors="replace")
        os.close(m_out)
    if not stderr_pty:
        err_str=p.stderr.read()
    else:
        while True:
            r,_,_=select.select([m_err], [], [], 0.5)
            if not r: break
            try:
                data=os.read(m_err, 4096)
                if not data: break
                err_bytes+=data
            except: break
        err_str=err_bytes.decode(errors="replace")
        os.close(m_err)
    p.wait(timeout=5)
    return out_str, err_str

for so,se,fv in [(False,False,None),(False,False,"1"),(False,True,None),(True,False,None),(True,True,None)]:
